package dev.rodrigo.cameraxlab;

import android.Manifest; import android.content.ContentValues; import android.content.pm.PackageManager; import android.os.Bundle; import android.provider.MediaStore; import android.widget.*;
import androidx.activity.ComponentActivity; import androidx.activity.result.ActivityResultLauncher; import androidx.activity.result.contract.ActivityResultContracts; import androidx.camera.core.*; import androidx.camera.lifecycle.ProcessCameraProvider; import androidx.camera.video.*; import androidx.camera.view.PreviewView; import androidx.core.content.ContextCompat;
import com.google.common.util.concurrent.ListenableFuture; import java.nio.ByteBuffer; import java.text.SimpleDateFormat; import java.util.*; import java.util.concurrent.*;

public class MainActivity extends ComponentActivity {
 private PreviewView preview; private TextView status; private ImageCapture imageCapture; private VideoCapture<Recorder> videoCapture; private Recording recording; private ExecutorService analyzerExecutor; private int lensFacing=CameraSelector.LENS_FACING_BACK;
 private final ActivityResultLauncher<String[]> permissions=registerForActivityResult(new ActivityResultContracts.RequestMultiplePermissions(), r->startCamera());
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main); preview=findViewById(R.id.preview);status=findViewById(R.id.status);analyzerExecutor=Executors.newSingleThreadExecutor();findViewById(R.id.photo).setOnClickListener(v->takePhoto());findViewById(R.id.video).setOnClickListener(v->toggleVideo());findViewById(R.id.switch_camera).setOnClickListener(v->{lensFacing=lensFacing==1?0:1;startCamera();}); if(ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)permissions.launch(new String[]{Manifest.permission.CAMERA,Manifest.permission.RECORD_AUDIO});else startCamera();}
 private void startCamera(){if(ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){status.setText("Camera permission required");return;} ListenableFuture<ProcessCameraProvider> f=ProcessCameraProvider.getInstance(this);f.addListener(()->{try{ProcessCameraProvider p=f.get();p.unbindAll(); Preview pv=new Preview.Builder().build();pv.setSurfaceProvider(preview.getSurfaceProvider());imageCapture=new ImageCapture.Builder().build(); Recorder rec=new Recorder.Builder().setQualitySelector(QualitySelector.from(Quality.HD)).build();videoCapture=VideoCapture.withOutput(rec);ImageAnalysis analysis=new ImageAnalysis.Builder().setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST).build();analysis.setAnalyzer(analyzerExecutor,img->{ByteBuffer y=img.getPlanes()[0].getBuffer();long sum=0;int n=y.remaining();while(y.hasRemaining())sum+=(y.get()&0xff);int luma=n==0?0:(int)(sum/n);runOnUiThread(()->status.setText("Live luma: "+luma));img.close();});CameraSelector selector=new CameraSelector.Builder().requireLensFacing(lensFacing).build();p.bindToLifecycle(this,selector,pv,imageCapture,analysis,videoCapture);}catch(Exception e){status.setText("Camera unavailable: "+e.getMessage());}},ContextCompat.getMainExecutor(this));}
 private String name(){return new SimpleDateFormat("yyyyMMdd-HHmmss",Locale.US).format(new Date());}
 private void takePhoto(){if(imageCapture==null)return;ContentValues cv=new ContentValues();cv.put(MediaStore.MediaColumns.DISPLAY_NAME,"IMG-"+name());cv.put(MediaStore.MediaColumns.MIME_TYPE,"image/jpeg");ImageCapture.OutputFileOptions o=new ImageCapture.OutputFileOptions.Builder(getContentResolver(),MediaStore.Images.Media.EXTERNAL_CONTENT_URI,cv).build();imageCapture.takePicture(o,ContextCompat.getMainExecutor(this),new ImageCapture.OnImageSavedCallback(){public void onImageSaved(ImageCapture.OutputFileResults r){status.setText("Photo saved: "+r.getSavedUri());}public void onError(ImageCaptureException e){status.setText("Photo error: "+e.getMessage());}});}
 private void toggleVideo(){if(recording!=null){recording.stop();recording=null;return;} if(videoCapture==null)return;ContentValues cv=new ContentValues();cv.put(MediaStore.MediaColumns.DISPLAY_NAME,"VID-"+name());cv.put(MediaStore.MediaColumns.MIME_TYPE,"video/mp4");MediaStoreOutputOptions o=new MediaStoreOutputOptions.Builder(getContentResolver(),MediaStore.Video.Media.EXTERNAL_CONTENT_URI).setContentValues(cv).build();PendingRecording pr=videoCapture.getOutput().prepareRecording(this,o);if(ContextCompat.checkSelfPermission(this,Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED)pr=pr.withAudioEnabled();recording=pr.start(ContextCompat.getMainExecutor(this),e->{if(e instanceof VideoRecordEvent.Start)status.setText("Recording…");else if(e instanceof VideoRecordEvent.Finalize){VideoRecordEvent.Finalize f=(VideoRecordEvent.Finalize)e;status.setText(f.hasError()?"Video error: "+f.getError():"Video saved: "+f.getOutputResults().getOutputUri());recording=null;}});}
 @Override protected void onDestroy(){super.onDestroy();analyzerExecutor.shutdown();}
}